<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free PDF Page Counter Online','description'=>'Count the number of pages in a PDF directly in your browser.','url'=>'https://smarttoolz.in/tools/pdf-page-counter/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">PDF PAGE COUNTER</span><h1>PDF Page Counter</h1><p>Drop in a PDF and instantly see its page count.</p></section><section class="tool-workspace"><div class="tool-panel"><label>PDF file<input id="f" type="file" accept="application/pdf"></label><p id="out" style="font-size:22px;font-weight:800"></p></div></section></main><script src="https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js"></script><script>(()=>{const f=document.getElementById('f'),o=document.getElementById('out');f.onchange=async()=>{let x=f.files[0];if(!x){return}try{let p=await PDFLib.PDFDocument.load(await x.arrayBuffer());o.textContent=`${p.getPageCount()} page${p.getPageCount()===1?'':'s'}` }catch(e){o.textContent='Could not read this PDF.'}}})();</script><?php smarttoolz_tool_page_end(); ?>